  }
}) }}

parameters.jsCode:
return $input.all().map((item, i) => {
  const q = $('Questions').all()[i].json;
  const a = item.json.answers.answer;
  return { json: {
    question: q.question,
    pick: a.choice,
    confidence: a.confidence,
    probabilities: a.probabilities,
    output_tokens: item.json.usage.output_tokens,
    latency_ms: Math.round(item.json.total_duration / 1e6)
  } };
});
